// CPU 的 binding mode 区分逐通道曲线、二维 strip 与三维 LUT；两类纹理槽均须有合法绑定。
// 布局与 ColorLutBakeParams 对应；曝光 buffer 必须是本帧 ExposureResolve 的产物。
struct ColorLutBakeParams {
    lut_size_and_flags: vec4<u32>,
